using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The MCP SDK discovers tools via [McpServerToolType] on the class
/// and [McpServerTool] on each method.
/// Constructor parameters are resolved from DI automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The MCP SDK instantiates this class per-call, injecting registered services.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the current weather forecast for a US state grid point.")]
    public async Task<string> GetForecast(
        [Description("The US state (e.g., CA, NY)")] string state,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        // Resolve grid point from coordinates
        var pointUrl = $"https://api.weather.gov/points/{latitude},{longitude}";
        var pointResponse = await _httpClient.GetFromJsonAsync<JsonElement>(pointUrl);

        var forecastUrl = pointResponse.GetProperty("properties").GetProperty("forecast").GetString()
            ?? throw new InvalidOperationException("Could not resolve forecast URL.");

        var forecast = await _httpClient.GetFromJsonAsync<JsonElement>(forecastUrl);
        var periods = forecast.GetProperty("properties").GetProperty("periods");

        // Return first 3 periods as a readable summary
        var results = periods.EnumerateArray()
            .Take(3)
            .Select(p => $"{p.GetProperty("name")}: {p.GetProperty("detailedForecast")}");

        return string.Join("\n\n", results);
    }

    [McpServerTool, Description("Get active weather alerts for a US state.")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code (e.g., CA, TX)")] string state)
    {
        var url = $"https://api.weather.gov/alerts/active/area/{state}";
        var response = await _httpClient.GetFromJsonAsync<JsonElement>(url);

        var features = response.GetProperty("features");
        if (features.GetArrayLength() == 0)
            return $"No active alerts for {state}.";

        var alerts = features.EnumerateArray()
            .Take(5)
            .Select(f =>
            {
                var props = f.GetProperty("properties");
                return $"[{props.GetProperty("severity")}] {props.GetProperty("headline")}";
            });

        return string.Join("\n", alerts);
    }
}

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using McpServer.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();  // Discovers all [McpServerToolType] classes

// Register a named HttpClient that the MCP SDK will inject into tool classes.
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.BaseAddress = new Uri("https://api.weather.gov");
    client.DefaultRequestHeaders.UserAgent.ParseAdd("mcp-server/1.0");
});

var app = builder.Build();
await app.RunAsync();

